<span class="line"><span style="color:#61AFEF;">redis-cli</span><span style="color:#D19A66;"> -h</span><span style="color:#D19A66;"> 10.0.0.5</span><span style="color:#D19A66;"> -a</span><span style="color:#98C379;"> your_strong_password_here</span><span style="color:#56B6C2;"> \\</span></span>
